        "**DSM-5 major depressive episode**: 5 or more of 9 symptoms for at least **2 weeks**. [DSM-5-TR 2022]",
        "At least one symptom must be **depressed mood or anhedonia** - without either it is not a depressive episode. [DSM-5-TR 2022]",
        "The other seven: appetite or weight change, insomnia or hypersomnia, psychomotor agitation or retardation, fatigue. [DSM-5-TR 2022]",
