        "PHQ-9 **10 or more**: 88% sensitivity and 88% specificity for major depression - the drug-treatment threshold. [NICE NG222 2022]",
        "PHQ-9 is validated in **Hindi, Tamil, Kannada, Malayalam** and other Indian languages - use the patient's own language version.",
        "**PHQ-9 item 9** - better off dead or hurting yourself - is a screening item, not a suicide risk assessment. [NICE NG222 2022]",
        "Any positive item 9 means a **direct suicide enquiry at the same visit**. [NICE NG222 2022]",
        "The tenth PHQ-9 question, on functional difficulty, is what decides **treatment intensity**. [NICE NG222 2022]",
