        "Step 3: have you thought about **how** you would do it?",
        "Step 4: have you made any **preparation** - kept anything aside, written anything?",
        "Step 5: have you **tried anything** before?",
        "Record **five dimensions** of risk: ideation, plan, means, intent and preparation, and past attempts. [MoHFW NSPS 2022]",
        "**Ideation**: passive (better off dead) or active (thoughts of killing myself).",
        "**Plan**: specific and lethal, or vague.",
        "**Means**: pesticide at home, sleeping tablets, a rope.",
        "**Intent and preparation**: giving away belongings, farewell notes.",
        "**A previous attempt is the strongest single predictor** of completed suicide. [WHO mhGAP 2.0 2016]",
        "Risk multipliers: **male sex**, age over 60 or under 25, living alone, recent loss or humiliation.",
