        "Mild depression: sleep hygiene, **30 minutes of walking daily**, problem-solving counselling, review in 2 weeks. [NICE NG222 2022]",
        "Add a drug in mild depression only if it persists beyond **4-6 weeks** or there is a past history of moderate depression. [NICE NG222 2022]",
        "**Moderate to severe depression (PHQ-9 10 or more)**: an **SSRI plus psychological support**. [NICE NG222 2022]",
        "**Escitalopram 10 mg once daily in the morning** - 5 mg in the elderly, maximum 20 mg. [NICE NG222 2022]",
