        "GAD worry is **hard to control** and causes distress or impairment. [DSM-5-TR 2022]",
        "GAD needs **3 or more** of restlessness, easy fatigue, poor concentration, irritability, muscle tension, sleep disturbance. [DSM-5-TR 2022]",
        "**Panic attack**: abrupt surge of intense fear peaking **within about 10 minutes** with 4 or more of 13 symptoms. [DSM-5-TR 2022]",
