            "Substance history: **caffeine, energy drinks, tobacco, cannabis**.",
            "Drug history: **salbutamol, thyroxine, decongestants**.",
            "Ask for **alcohol or benzodiazepine use and withdrawal**.",
            "Life context: marital and family stress, **domestic violence**, financial strain.",
            "Ask for a recent bereavement or a frightening illness in a relative - these commonly precede the first attack.",
