            "Investigations already done are adequate: **haemoglobin, blood glucose, TSH and a 12-lead ECG**. [NICE CG113 2020]",
            "State that **no further tests are needed** and record this in her file.",
            "Consider **Holter monitoring** only if palpitations are abrupt on-off with a documented rate **above 150**. [NICE CG113 2020]",
