        "Screen in recurrent gastritis or pancreatitis, and repeated trauma or road traffic injury. [NICE CG115 2011]",
        "Screen in poorly controlled diabetes and in **tuberculosis defaulters**.",
        "Screen the **husband of a woman presenting with depression or domestic violence**. [IPS CPG SUD 2018]",
        "**DSM-5 alcohol use disorder**: 2 or more of 11 criteria within 12 months. [DSM-5-TR 2022]",
        "The 11: larger amounts than intended, failed attempts to cut down, time spent obtaining or recovering, craving. [DSM-5-TR 2022]",
        "...failure of role obligations, use despite social problems, activities given up, use in hazardous situations. [DSM-5-TR 2022]",
        "...use despite physical or psychological harm, **tolerance**, and **withdrawal**. [DSM-5-TR 2022]",
