        "**Minor withdrawal at 6-12 hours**: tremor, anxiety, sweating, nausea, insomnia, tachycardia. [NICE CG100 2017]",
        "**Alcoholic hallucinosis at 12-24 hours** - usually visual, with a **clear sensorium and intact orientation**. [NICE CG100 2017]",
