        "**CIWA-Ar has 10 items**. [CIWA-Ar, Sullivan 1989]",
        "The 10: nausea and vomiting, tremor, paroxysmal sweats, anxiety, agitation, tactile, auditory and visual disturbance, headache, orientation. [CIWA-Ar, Sullivan 1989]",
        "Nine items score **0-7** and orientation scores **0-4**, giving a **maximum of 67**. [CIWA-Ar, Sullivan 1989]",
        "**CIWA-Ar under 8 is mild** - no drug needed if the patient is stable. [CIWA-Ar, Sullivan 1989]",
        "**CIWA-Ar 8-15 is moderate** - treat with a benzodiazepine. [CIWA-Ar, Sullivan 1989]",
        "**CIWA-Ar 16 or more is severe**, with a high risk of seizures and delirium tremens. [CIWA-Ar, Sullivan 1989]",
        "A score of **15 or more, or any score with confusion, mandates admission**. [NICE CG100 2017]",
        "**Symptom-triggered dosing is preferred** where nursing observation is reliable.",
        "Symptom-triggered: score CIWA-Ar hourly, give a benzodiazepine dose whenever the score is **8-10 or more**, rescore in an hour. [CIWA-Ar, Sullivan 1989]",
        "Symptom-triggered dosing **uses less drug and shortens treatment** than a fixed schedule.",
        "**Fixed-dose tapering is safer in home detoxification** and wherever hourly scoring is impossible - most of Indian general practice. [NICE CG100 2017]",
