        "CIWA-Ar scores **falsely high in delirium of any cause**. [CIWA-Ar, Sullivan 1989]",
        "Check **capillary glucose, sodium, potassium, magnesium, calcium, urea and creatinine, and liver function** in every case. [NICE CG100 2017]",
        "Actively **search for infection** in every withdrawing drinker.",
        "**Hypoglycaemia, hyponatraemia and hypomagnesaemia** are common in the malnourished drinker and each lowers the seizure threshold. [NICE CG100 2017]",
