        "**Diazepam 10 mg four times daily tapering over 5-7 days** is an equally acceptable alternative.",
        "Diazepam is **cheaper and more widely available in India** than chlordiazepoxide. [NICE CG100 2017]",
        "**Lorazepam 2-4 mg six-hourly tapering** in significant liver disease, the elderly and respiratory compromise.",
