        "Then **thiamine 250 mg daily for 5 days** after the high-dose phase. [NICE CG100 2017]",
        "**Wernicke encephalopathy triad: confusion, ophthalmoplegia or nystagmus, and ataxia**. [NICE CG100 2017]",
        "**Fewer than 1 in 5 show all three** - treat a drinker on any one feature.",
        "Untreated Wernicke progresses to irreversible **Korsakoff psychosis**. [NICE CG100 2017]",
