        "**Ask in local terms: khaini, gutkha, zarda, mishri, mawa, paan masala, betel quid** - the chewer answers no to 'do you smoke'. [GATS-2 2016-17]",
        "**Name the smoked forms too: bidi, cigarette, hookah, chillum** - bidi outsells cigarette in India and users do not count it as smoking. [GATS-2 2016-17]",
