        "**Tobacco cancers: lung, oral cavity, larynx, oesophagus, pancreas, bladder and cervix** - so the link must be made explicit at diagnosis. [WHO 2023]",
        "**Oral cancer and oral submucous fibrosis are the signature Indian diseases** - driven by smokeless tobacco and areca nut, and India leads both. [WHO 2023]",
        "**Record tobacco use as a vital sign at every visit** - documented status is what converts an intention to advise into an actual quit attempt. [USPHS 2008]",
        "**Brief advice under three minutes raises quit rates by 2-3% absolute** - small per patient, the highest-yield preventive act across a list. [USPHS 2008]",
        "**Advice plus behavioural support plus a drug gives 25-30% abstinence at 6-12 months** - against 3-5% for an unaided attempt. [USPHS 2008]",
        "**Quitting before 40 avoids about 90% of the excess mortality** - so age is never a reason to withhold the advice. [WHO 2023]",
        "**Pulse and blood pressure fall within 20 minutes and carbon monoxide clears by 12-24 hours** - the earliest gains to quote to a wavering patient. [WHO 2023]",
        "**Myocardial infarction risk halves at 1 year and lung cancer risk at 10 years** - stroke risk approaches a non-smoker's by 5-15 years. [WHO 2023]",
