        "**Plan a substitute for each high-risk situation** - after meals, with tea, with alcohol, with smoking friends, at times of stress. [USPHS 2008]",
        "**Prescribe pharmacotherapy at the same visit unless contraindicated** - counselling alone leaves most of the achievable benefit unclaimed. [USPHS 2008]",
        "**ARRANGE follow-up in week 1, at 2 weeks, at 1 month and monthly for 3 months** - because most relapses occur in the first two weeks. [USPHS 2008]",
        "**Treat a lapse as information, not failure** - congratulating the abstinent days and naming the trigger keeps the attempt alive. [USPHS 2008]",
        "**For the patient not ready to quit, run the 5 R's at every visit** - Relevance, Risks, Rewards, Roadblocks, Repetition. [USPHS 2008]",
