        "**Also offer it if first use is within 30 minutes of waking or an attempt has failed** - both mark dependence too high for advice alone. [NICE NG209 2021]",
        "**Patch 21 mg/24 h for 6 weeks, then 14 mg for 2 weeks, then 7 mg for 2 weeks** - the standard course for more than 10 a day. [NICE NG209 2021]",
