        "**The National Tobacco Control Programme funds Tobacco Cessation Centres at district level** - some supply free nicotine replacement. [NTCP 2023]",
        "**mCessation: a missed call to 011-22901701 starts free structured SMS support** - available in several Indian languages. [NTCP 2023]",
        "**The National Tobacco Quitline is 1800-11-2356** - free telephone counselling, and the number to write on the prescription at the quit visit. [NTCP 2023]",
        "**COTPA 2003 section 4 bans smoking in public places** - and section 5 bans all direct and indirect tobacco advertising. [COTPA 2003]",
        "**COTPA 2003 section 6 bans sale to or by minors under 18 and sale within 100 yards of an educational institution** - the clause most often asked. [COTPA 2003]",
        "**COTPA 2003 section 7 requires pictorial warnings over 85% of both sides of the pack** - among the largest mandated warnings in the world. [COTPA 2003]",
        "**The Prohibition of Electronic Cigarettes Act 2019 bans production, sale, import and advertisement** - no legal vaping substitute exists. [PECA 2019]",
        "**India has ratified the WHO Framework Convention on Tobacco Control** - COTPA and the NTCP are its domestic instruments. [WHO FCTC 2005]",
