        "**They are on the Beers list as potentially inappropriate in older adults** - long-acting diazepam and nitrazepam are the worst choices. [Beers 2023]",
        "**Avoid benzodiazepines altogether in chronic insomnia** - harm accumulates with duration while the hypnotic benefit does not. [Beers 2023]",
        "**Mirtazapine 7.5-15 mg at night for insomnia with comorbid depression** - it also improves appetite, at the cost of weight gain. [AASM 2017]",
        "**Trazodone 25-100 mg at night is the alternative sedating antidepressant** - used for sleep well below its antidepressant range. [AASM 2017]",
        "**Low-dose amitriptyline 10-25 mg at night where there is also chronic pain** - with the usual anticholinergic and cardiac cautions. [AASM 2017]",
        "**Never give amitriptyline to a patient at suicide risk** - tricyclic overdose is cardiotoxic and a small dispensed supply can be lethal. [AASM 2017]",
        "**Doxepin 3-6 mg is licensed specifically for sleep maintenance insomnia** - histamine H1 blockade at that dose is what holds sleep. [AASM 2017]",
        "**Melatonin 2 mg prolonged release, one to two hours before bed, for up to 13 weeks** - licensed for insomnia in adults over 55. [AASM 2017]",
        "**Melatonin's place is jet lag, shift work, circadian disorders and children with neurodisability** - its effect in ordinary insomnia is small. [AASM 2017]",
        "**Sedating antihistamines such as diphenhydramine and promethazine are not recommended** - tolerance develops within days of nightly use. [AASM 2017]",
