        "**Other clozapine hazards are myocarditis, seizures, hypersalivation and constipation** - the constipation can become life-threatening ileus. [NICE CG178 2014]",
        "**Marked weight gain is the other clozapine cost** - accepted because it is the only effective drug in resistant schizophrenia. [NICE CG178 2014]",
        "**Long-acting injectables answer repeated relapse from non-adherence** - risperidone, paliperidone, flupentixol or haloperidol decanoate. [NICE CG178 2014]",
        "**Non-adherence is the commonest single reason for readmission** - so the injectable is offered early, not kept as a last resort. [NICE CG178 2014]",
